layer.fontFaces:
@font-face { font-family: Jost; font-style: normal; font-weight: 400; font-display: swap; src: local("Jost Regular Regular"), local("Jost-Regular"), local("Jost* Book"), local("Jost-Book"), url("{{assets}}/doks_demo/jost-v4-latin-regular.woff2") format("woff2"), url("{{assets}}/doks_demo/jost-v4-latin-regular.woff") format("woff"); }
@font-face { font-family: Jost; font-style: normal; font-weight: 500; font-display: swap; src: local("Jost Regular Medium"), local("JostRoman-Medium"), local("Jost* Medium"), local("Jost-Medium"), url("{{assets}}/doks_demo/jost-v4-latin-500.woff2") format("woff2"), url("{{assets}}/doks_demo/jost-v4-latin-500.woff") format("woff"); }
@font-face { font-family: Jost; font-style: normal; font-weight: 700; font-display: swap; src: local("Jost Regular Bold"), local("JostRoman-Bold"), local("Jost* Bold"), local("Jost-Bold"), url("{{assets}}/doks_demo/jost-v4-latin-700.woff2") format("woff2"), url("{{assets}}/doks_demo/jost-v4-latin-700.woff") format("woff"); }
@font-face { font-family: Jost; font-style: italic; font-weight: 400; font-display: swap; src: local("Jost Italic Italic"), local("Jost-Italic"), local("Jost* BookItalic"), local("Jost-BookItalic"), url("{{assets}}/doks_demo/jost-v4-latin-italic.woff2") format("woff2"), url("{{assets}}/doks_demo/jost-v4-latin-italic.woff") format("woff"); }

layer.css:
[data-ryt="footer"] { color: color-mix(in srgb, var(--ryt-text) 75%, transparent); border-top: 1px solid rgb(233, 236, 239); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: rgb(0, 0, 0); border-radius: 0px; font-family: Jost, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 22px; font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 0, 0); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: Jost, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 18px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 8px; padding-bottom: 8px; padding-left: 8px; transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out }
[data-ryt="button"] { color: var(--ryt-bg); background-color: rgb(51, 71, 255); border-top: 1px solid rgb(51, 71, 255); border-right: 1px solid rgb(51, 71, 255); border-bottom: 1px solid rgb(51, 71, 255); border-left: 1px solid rgb(51, 71, 255); border-radius: 800px; font-family: Jost, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 32px; padding-bottom: 8px; padding-left: 32px; transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: rgb(51, 71, 255); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(51, 71, 255); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: Jost, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", "Noto Sans", "Liberation Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji"; font-size: 49.2px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="button"]:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #fff; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; background-color: rgb(17%, 23.8%, 85%); text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="nav"] a:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgba(0, 0, 0, 0.8); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgb(51, 71, 255) }
[data-ryt="brand"]:hover { text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: rgba(0, 0, 0, 1); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
